window.VALDRIEN_INITIAL_CONTENT = {"format":2,"world":{"name":"Valdrien","motto":"Ein Land voller Abenteuer, Geheimnisse und Gefährten, denen du nicht ganz trauen solltest."},"adventures":{"forest":{"pos":10,"name":"Die Prüfung der Waldgilde","setting":"Draußen · für Wanderungen und Spaziergänge","story":{"title":"Willkommen, Anwärter der Waldgilde!","paragraphs":["Tief verborgen zwischen uralten Bäumen liegt der Sitz der legendären Waldgilde. Seit Jahrhunderten beschützt sie die Bewohner des Waldes, bewahrt seine magischen Geheimnisse und stellt sich Gefahren, denen andere nicht gewachsen sind.","Doch die Gilde nimmt nicht jeden auf. Nur wer Mut, Geschick, Verstand und Gerissenheit beweist, darf Teil ihrer Gemeinschaft werden.","Ihr wurdet aus allen Winkeln des Landes ausgewählt, um euch der Aufnahmeprüfung zu stellen. Jeder von euch kennt seine eigenen Fähigkeiten, doch eure Mitstreiter sind Fremde. Wer ist Freund, wer Rivale? Und wer verbirgt mehr, als er preisgibt?","Stellt euch den Prüfungen, meistert unerwartete Begegnungen und sammelt Münzen. Lernt eure Mitstreiter kennen, durchschaut ihre Absichten und beweist, dass ihr den Herausforderungen des Waldes gewachsen seid.","Am Ende wird nur einer von euch den begehrten Titel erringen und in die Reihen der Waldgilde aufgenommen werden."],"closing":"Die Prüfung beginnt! Beweist euren Mut und zeigt dem Wald, dass ihr würdig seid!"},"epilogue":{"title":"Die Aufnahme in die Waldgilde","before":["Die Prüfung ist vollbracht!","Die Münzen sind gezählt, und es steht fest, wer gewonnen hat:"],"after":["Mit Mut, Geschick und Verstand hast du deine Mitstreiter übertroffen und dich als würdig erwiesen.","Im Namen der Waldgilde heißen wir dich willkommen! Mögest du ihre Geheimnisse bewahren, den Wald beschützen und viele Abenteuer bestehen.","Herzlichen Glückwunsch, {winner}! Dein Abenteuer als Mitglied der Waldgilde beginnt jetzt!"]},"terms":{"question":"Wer stellt sich der Prüfung?","player":"Anwärter","plural":"Anwärter","dative":"Anwärtern","finish":"Prüfung beenden"},"roles":{"magnus":{"pos":10,"name":"Magnus","title":"der Mundschenk","startingCoins":4,"background":"Magnus sorgt dafür, dass auf keiner Reise die Kehlen trocken bleiben. Ob Wasser, Saft oder ein kräftiger Schluck aus dem Krug – er kennt den Wert guter Vorräte und einer wohlverdienten Pause.","character":"","traits":["Gastfreundlich, gesellig und aufmerksam.","Hat Getränke und Vorräte im Blick.","Schlägt gern eine gemeinsame Trinkpause vor."],"ability":{"name":"Schatzsucher","text":"Einmal im Spiel erhält Magnus 3 Münzen aus der Spielbank.","mechanic":"treasureHunter"},"task":{"name":"Münzhorter","text":"Gib während der gesamten Partie keine Münzen aus und besitze am Ende mindestens so viele Münzen wie zu Beginn. Münzen, die du beim Raten setzt, zählen nicht als Ausgabe.","bonus":3}},"elara":{"pos":20,"name":"Elara","title":"die Waldläuferin","startingCoins":5,"background":"Elara kennt die verschlungenen Wege des Waldes und bemerkt Dinge, an denen andere achtlos vorbeigehen. Sie ist unabhängig, wachsam und immer bereit, den nächsten Hinweis zu entdecken.","character":"","traits":["Beobachtet aufmerksam ihre Umgebung.","Wirkt selbstständig und orientiert sich gern.","Entdeckt kleine Details, Wegweiser oder besondere Lichtungen."],"ability":{"name":"Pfadfinderin","text":"Einmal im Spiel darf Elara die nächste Ereigniskarte ansehen, bevor entschieden wird, ob sie gespielt wird.","mechanic":"pathfinder"},"task":{"name":"Wegkundige","text":"Fotografiere zwei unterschiedliche Wegmarkierungen oder Wanderwegschilder, ohne den Weg zu verlassen.","bonus":2}},"morgana":{"pos":30,"name":"Morgana","title":"die Kräuterhexe","startingCoins":3,"background":"Morgana kennt die alten Geschichten über Pflanzen, Wurzeln und geheimnisvolle Waldgewächse. Sie beobachtet lieber erst, bevor sie handelt, und scheint für alles einen kleinen Zauber oder Rat zu kennen.","character":"","traits":["Geheimnisvoll, ruhig und neugierig.","Interessiert sich für Pflanzen, Pilze und Naturdetails.","Gibt gern rätselhafte Ratschläge oder spricht von alten Rezepturen."],"ability":{"name":"Glücksbringerin","text":"Einmal im Spiel kann Morgana verhindern, dass sie durch ein Ereignis Münzen verliert. Sie muss die Fähigkeit beim drohenden Verlust einsetzen.","mechanic":"luckBringer"},"task":{"name":"Sammlerin der Eindrücke","text":"Mache drei Fotos: einen Baum, eine Kleinigkeit am Boden und eine besondere Aussicht.","bonus":3}},"finnian":{"pos":40,"name":"Finnian","title":"der Wald-Barde","startingCoins":4,"background":"Finnian sammelt Geschichten, Legenden und Lieder, die von Generation zu Generation weitergegeben werden. Er liebt große Auftritte, dramatische Erzählungen und die kleinen Momente, aus denen später Legenden werden.","character":"","traits":["Wortgewandt, kreativ und ausdrucksstark.","Erzählt gern Geschichten oder kommentiert Ereignisse dramatisch.","Hat oft einen Spruch, Reim oder eine passende Redewendung parat."],"ability":{"name":"Goldfinger","text":"Direkt nachdem du ein Minispiel gewonnen hast, verdoppelst du deinen Gewinn.","mechanic":"goldFinger"},"task":{"name":"Chronist","text":"Sammle drei unterschiedliche Nachweise aus dem Abenteuer, z. B. ein Foto, eine erfüllte Aufgabe und einen gewonnenen Minispielbonus.","bonus":3}},"roderick":{"pos":50,"name":"Roderick","title":"der Waldritter","startingCoins":5,"background":"Roderick hat geschworen, die Bewohner des Waldes und die Geheimnisse der Waldgilde zu beschützen. Er handelt entschlossen, nimmt Herausforderungen ernst und gibt nicht so schnell auf.","character":"","traits":["Mutig, pflichtbewusst und entschlossen.","Stellt sich gern Herausforderungen.","Spricht von Ehre, Mut und dem Einhalten von Versprechen."],"ability":{"name":"Das Turnier","text":"Sobald ein Minispiel gezogen wurde, bei dem du mitspielst, und Regeln und Gegner feststehen, kündigst du deinen Sieg an. Gewinnst du, erhältst du zusätzlich zu deinem Gewinn 1 Münze von jedem Mitspieler des Minispiels. (Info: Bei jedem Minispiel, bei dem du mitspielst, erscheint vor dem Start ein Knopf, mit dem du die Fähigkeit aktivierst.)","mechanic":"marksman"},"task":{"name":"Glücksstein","text":"Finde einen flachen Stein, der bereits auf dem Boden liegt, und trage ihn bis zum Ende bei dir.","bonus":2}},"theobald":{"pos":60,"name":"Theobald","title":"der Waldgelehrte","startingCoins":4,"background":"Theobald studiert die Legenden der Waldgilde und glaubt, dass Wissen mächtiger sein kann als jedes Schwert. Er analysiert Situationen, stellt kluge Fragen und versucht, stets einen Schritt voraus zu sein.","character":"","traits":["Nachdenklich, wissbegierig und analytisch.","Erklärt gern Zusammenhänge oder stellt ungewöhnliche Fragen.","Wirkt, als würde er jedes Detail auf seine Bedeutung prüfen."],"ability":{"name":"Schicksalswender","text":"Einmal im Spiel darf Theobald zwei Ereigniskarten ziehen und entscheiden, welche gespielt wird. Die andere kommt unter den Stapel.","mechanic":"fateTurner"},"task":{"name":"Kartograf","text":"Mache ein Foto oder einen Screenshot der Wanderkarte bzw. deiner Route.","bonus":2}},"liora":{"pos":70,"name":"Liora","title":"die Waldfee","startingCoins":3,"background":"Liora ist eng mit der Magie des Waldes verbunden. Sie wirkt verspielt und freundlich, doch hinter ihrem Lächeln steckt ein scharfer Verstand. Manchmal scheint ihr das Glück einfach in den Schoß zu fallen.","character":"","traits":["Verspielt, charmant und ein wenig geheimnisvoll.","Begeistert sich für schöne Kleinigkeiten und magische Zufälle.","Reagiert auf Ereignisse gern mit Staunen oder schelmischen Kommentaren."],"ability":{"name":"Glücksfee","text":"Du wählst Kopf oder Zahl, und die App wirft eine Münze. Liegst du richtig, nimmst du dem reichsten Mitspieler die Hälfte seiner Münzen weg (aufgerundet). Bist du selbst der Reichste, trifft es den Zweitreichsten. Bei Gleichstand wählst du einen davon aus. Liegst du falsch, verlierst du alle deine Münzen an die Bank.","mechanic":"luckyFairy"},"task":{"name":"Lichtfängerin","text":"Fotografiere Sonnenlicht, das sichtbar durch die Bäume fällt.","bonus":2}}},"minigames":{"stein-blatt-zapfen":{"pos":10,"name":"Stein, Blatt, Zapfen","category":"duel","description":"Wie Schere, Stein, Papier: Der Stein zerdrückt den Zapfen, der Zapfen durchsticht das Blatt, das Blatt umhüllt den Stein. Wer zuerst 2 Runden gewinnt, siegt.","reward":{"winner":2}},"blinzelduell":{"pos":20,"name":"Blinzelduell","category":"duel","description":"Beide schauen sich in die Augen. Wer zuerst blinzelt, wegschaut oder lacht, verliert. Die anderen dürfen versuchen, sie zum Lachen zu bringen, aber ohne sie zu berühren.","reward":{"winner":2}},"zapfenwurf":{"pos":30,"name":"Zapfenwurf","category":"duel","description":"Jeder sucht sich einen Tannenzapfen vom Boden. Gemeinsam wählt ihr einen Baumstamm am Wegesrand als Ziel. Abwechselnd hat jeder drei Würfe. Wer öfter trifft, gewinnt. Nur werfen, wenn niemand in der Nähe ist, und die Zapfen danach zurücklegen.","reward":{"winner":2}},"wortgefecht":{"pos":40,"name":"Wortgefecht","category":"duel","description":"Ihr nennt abwechselnd ein Tier des Waldes. Wer länger als 5 Sekunden überlegt oder etwas wiederholt, verliert.","reward":{"winner":2,"loser":-1}},"der-schnellste-blick":{"pos":50,"name":"Der schnellste Blick","category":"duel","description":"Die anderen nennen etwas, das am Wegesrand zu finden ist, zum Beispiel »etwas Rotes« oder »ein Blatt mit Loch«. Wer es zuerst entdeckt und zeigt, gewinnt. Den Weg nicht verlassen!","reward":{"winner":2}},"schrittschaetzer":{"pos":60,"name":"Schrittschätzer","category":"all","description":"Wählt einen Baum oder Punkt am Weg. Jeder schätzt, wie viele Schritte es bis dorthin sind. Einer zählt beim Gehen mit. Wer am nächsten dran ist, gewinnt.","reward":{"winner":2}},"welches-tier-bin-ich":{"pos":70,"name":"Welches Tier bin ich?","category":"all","description":"Einer denkt sich ein Tier des Waldes aus, die anderen stellen reihum Ja-Nein-Fragen. Wer es errät, gewinnt. Nach 20 Fragen ohne Treffer gewinnt der, der es sich ausgedacht hat.","reward":{"winner":2}},"das-gedaechtnis-des-waldes":{"pos":80,"name":"Das Gedächtnis des Waldes","category":"all","description":"Der Erste sagt »Im Wald fand ich …« und nennt etwas. Jeder wiederholt alles Bisherige und fügt etwas hinzu. Wer etwas vergisst oder durcheinanderbringt, scheidet aus. Der Letzte gewinnt.","reward":{"winner":3}},"das-gildenzeichen":{"pos":90,"name":"Das Gildenzeichen","category":"all","description":"Alle zählen gemeinsam bis drei und zeigen dann mit den Fingern eine Zahl von 0 bis 5. Gewonnen hat, wer die höchste Zahl zeigt, die sonst niemand gezeigt hat. Gibt es keinen, wird wiederholt.","reward":{"winner":2}},"der-hoechste-turm":{"pos":100,"name":"Der höchste Turm","category":"all","description":"Jeder baut in einer Minute aus Steinchen und Zapfen vom Wegesrand einen Turm. Der höchste Turm, der noch steht, gewinnt. Danach wieder abbauen.","reward":{"winner":2}},"der-waldrichter":{"pos":110,"name":"Der Waldrichter","category":"all","description":"Jeder sucht in zwei Minuten den ungewöhnlichsten Gegenstand am Boden, ohne den Weg zu verlassen. Wer die wenigsten Münzen hat, spielt nicht mit, sondern ist Richter und kürt den Sieger.","reward":{"winner":2,"judge":1}},"ein-langer-atem":{"pos":120,"name":"Ein langer Atem","category":"all","description":"Alle holen gleichzeitig Luft und summen. Wer am längsten durchhält, gewinnt.","reward":{"winner":2}},"der-faehrtenleser":{"pos":130,"name":"Der Fährtenleser","category":"oneVsAll","description":"Der Einzelne versteckt einen kleinen Stein in einer Hand hinter dem Rücken. Die anderen einigen sich gemeinsam auf links oder rechts. Drei Runden. Errät die Gruppe mindestens 2 von 3, gewinnt sie.","reward":{"solo":3,"group":1}},"die-geschichte-des-barden":{"pos":140,"name":"Die Geschichte des Barden","category":"oneVsAll","description":"Die Gruppe zeigt dem Einzelnen drei Dinge vom Wegesrand. Er muss in einer Minute eine Geschichte erzählen, in der alle drei vorkommen.","reward":{"solo":3,"fail":-1}},"der-waechter-der-bruecke":{"pos":150,"name":"Der Wächter der Brücke","category":"oneVsAll","description":"Der Einzelne denkt an etwas, das alle gerade sehen können. Die Gruppe hat zusammen 10 Ja-Nein-Fragen, um es zu erraten.","reward":{"solo":3,"group":1}},"pantomime-des-waldes":{"pos":160,"name":"Pantomime des Waldes","category":"team","description":"Abwechselnd stellt ein Spieler etwas aus dem Wald pantomimisch dar, zum Beispiel ein Tier oder einen Baum. Sein Team hat 30 Sekunden zum Raten. Nach drei Runden pro Team gewinnt das Team mit mehr Treffern.","reward":{"team":1}},"gemeinsam-schaetzen":{"pos":170,"name":"Gemeinsam schätzen","category":"team","description":"Wählt einen Baum oder Punkt am Weg. Jedes Team einigt sich auf eine Schätzung, wie viele Schritte es bis dorthin sind. Einer zählt beim Gehen mit. Das Team, das näher dran ist, gewinnt.","reward":{"team":1}},"die-zapfenjagd":{"pos":180,"name":"Die Zapfenjagd","category":"team","description":"Jedes Team sammelt zwei Minuten lang Tannenzapfen, die am Wegesrand liegen, ohne den Weg zu verlassen. Das Team mit mehr Zapfen gewinnt. Danach alles zurücklegen.","reward":{"team":2}},"das-waldalphabet":{"pos":190,"name":"Das Waldalphabet","category":"team","description":"Die Teams nennen abwechselnd etwas aus dem Wald nach dem Alphabet: A wie Ameise, B wie Buche … Wer nicht weiterweiß, verliert. Schwierige Buchstaben wie Q oder X dürft ihr überspringen.","reward":{"team":1}},"der-riese-und-die-zwerge":{"pos":200,"name":"Der Riese und die Zwerge","category":"uneven","description":"Der Riese nennt in 45 Sekunden so viele Waldwörter wie möglich. Danach nennen die zwei Zwerge abwechselnd Wörter, aber nur 30 Sekunden lang. Wer mehr schafft, gewinnt.","reward":{"single":3,"pair":2,"singleName":"Riese","pairName":"Zwerge"}}},"events":{"goldregen":{"pos":10,"name":"Goldregen","category":"Segen","visibility":"public","description":"Ein Sonnenstrahl lässt etwas im Laub glitzern. Alle erhalten 1 Münze aus der Spielbank.","effect":"goldRain"},"der-steuereintreiber":{"pos":20,"name":"Der Steuereintreiber","category":"Fluch","visibility":"public","description":"Ein Bote des Fürsten verlangt seinen Anteil. Alle zahlen 1 Münze an die Spielbank. Wer keine Münze hat, kommt davon.","effect":"tax"},"gunst-der-waldgeister":{"pos":30,"name":"Gunst der Waldgeister","category":"Segen","visibility":"public","description":"Die Geister helfen den Schwachen. Wer die wenigsten Münzen hat, erhält 3 Münzen. Bei Gleichstand sind alle Gleichplatzierten betroffen.","effect":"favor"},"neid-der-gilde":{"pos":40,"name":"Neid der Gilde","category":"Fluch","visibility":"public","description":"Wer die meisten Münzen hat, muss 2 davon an den Spieler mit den wenigsten Münzen abgeben. Bei Gleichstand sind alle Gleichplatzierten betroffen. Jeder der Reichsten gibt 2 ab, jeder der Ärmsten erhält 2.","effect":"envy"},"entlarvt":{"pos":50,"name":"Entlarvt!","category":"Fluch","visibility":"public","description":"Wer sein Geheimnis verloren hat, ist verwundbar. Alle, deren Rolle schon erraten wurde, verlieren 1 Münze.","effect":"exposed","requiresRoles":true},"meister-der-tarnung":{"pos":60,"name":"Meister der Tarnung","category":"Segen","visibility":"public","description":"Alle, deren Rolle noch nicht erraten wurde, erhalten 1 Münze.","effect":"disguise","requiresRoles":true},"das-duell-an-der-bruecke":{"pos":70,"name":"Das Duell an der Brücke","category":"Duell","visibility":"public","description":"Wer die meisten und wer die wenigsten Münzen hat, treten in einem Minispiel gegeneinander an. Der Sieger erhält von jedem Verlierer 2 Münzen. Bei Gleichstand sind alle Gleichplatzierten betroffen. Sie treten alle mit an.","effect":"duel"},"das-grosse-kraeftemessen":{"pos":80,"name":"Das große Kräftemessen","category":"Alle gegen alle","visibility":"public","description":"Zieht ein Minispiel, bei dem alle gegeneinander antreten. Der Gewinner erhält die doppelte Belohnung.","effect":"contest"},"wettstreit-der-lager":{"pos":90,"name":"Wettstreit der Lager","category":"Team gegen Team","visibility":"public","description":"Die Entdeckten, deren Rolle erraten wurde, treten als Team gegen die Unentdeckten an. Jeder im Siegerteam erhält 1 Münze. Gibt es nur ein Lager, wird ein Alle-gegen-alle daraus, und der Sieger erhält 2 Münzen.","effect":"camps","requiresRoles":true},"der-verfluchte-beutel":{"pos":100,"name":"Der verfluchte Beutel","category":"Fluch mit Ausweg","visibility":"public","description":"Wer die meisten Münzen hat, verliert 2 Münzen, außer er wählt einen Herausforderer und gewinnt ein Duell gegen ihn. Bei Gleichstand sind alle Gleichplatzierten betroffen. Jeder kämpft für sich.","effect":"purse"},"das-orakel-spricht":{"pos":110,"name":"Das Orakel spricht","category":"Enthüllung","visibility":"public","description":"Wer die meisten Münzen hat, muss ein wahres Erkennungsmerkmal seiner Rolle verraten oder 2 Münzen an die Spielbank zahlen. Bei Gleichstand sind alle Gleichplatzierten betroffen.","effect":"oracle","requiresRoles":true},"am-scheideweg":{"pos":120,"name":"Am Scheideweg","category":"Entscheidung","visibility":"public","description":"Wer die wenigsten Münzen hat, entscheidet: Entweder erhalten alle 1 Münze, oder er allein erhält 2. Bei Gleichstand sind alle Gleichplatzierten betroffen. Sie entscheiden gemeinsam, und bei der zweiten Wahl erhält jeder von ihnen 2.","effect":"crossroads"},"die-nacht-der-seher":{"pos":130,"name":"Die Nacht der Seher","category":"Segen, hält an","visibility":"public","description":"Bis zum nächsten Ereignis bringt ein richtiger Tipp beim Raten 5 statt 3 Münzen.","effect":"seers","requiresRoles":true},"stille-lichtung":{"pos":140,"name":"Stille Lichtung","category":"Ruhe","visibility":"public","description":"Nichts geschieht. Der Wald ist friedlich. Atmet durch und genießt den Moment.","effect":"calm"},"der-alte-wegweiser":{"pos":150,"name":"Der alte Wegweiser","category":"Ruhe","visibility":"public","description":"Ihr kommt an einem alten Wegweiser vorbei. Seine Schrift ist längst verwittert. Nichts geschieht, doch irgendwo beobachtet euch die Gilde.","effect":"calm"},"vogelgesang":{"pos":160,"name":"Vogelgesang","category":"Ruhe","visibility":"public","description":"Über euch singt eine Amsel. Nichts geschieht. Lauscht einen Moment, bevor es weitergeht.","effect":"calm"}}},"tavern":{"pos":20,"name":"Die Sturmnacht im Goldenen Krug","setting":"Drinnen · für einen Abend am Tisch mit Essen und Trinken","story":{"title":"Die Sturmnacht im Goldenen Krug","paragraphs":["Draußen tobt ein Sturm über Valdrien, wie ihn selbst die Alten noch nicht erlebt haben. Die Wege sind überschwemmt, die Brücken gesperrt, und so sitzt ihr fest: eine bunt gemischte Runde Reisender in der Taverne »Zum Goldenen Krug«.","Der Wirt stellt Krüge und eine dampfende Suppe auf den Tisch und macht euch ein Angebot: »Wer heute Nacht die meisten Münzen sammelt, dessen Name kommt an die Wand der Stammgäste. Und Stammgäste trinken bei mir für immer umsonst.«","Doch niemand an diesem Tisch ist der, für den er sich ausgibt. Jeder hat ein Geheimnis, und jeder will an diese Wand. Esst, trinkt, spielt und beobachtet eure Tischnachbarn genau."],"closing":"Bis der Sturm sich legt, ist noch viel Zeit. Die Nacht beginnt!"},"epilogue":{"title":"Ein neuer Stammgast","before":["Der Sturm hat sich gelegt, die Kerzen sind heruntergebrannt, und die Münzen sind gezählt.","Der Wirt nimmt Hammer und Nagel und hängt eine neue Tafel an die Wand:"],"after":["Willkommen unter den Stammgästen des Goldenen Krugs! Ab heute ist dein Krug nie mehr leer, und dein Name hängt für immer an dieser Wand.","Herzlichen Glückwunsch, {winner}! Die nächste Runde geht aufs Haus."]},"terms":{"question":"Wer sitzt mit am Tisch?","player":"Gast","plural":"Gäste","dative":"Gästen","finish":"Die Nacht beenden"},"roles":{"wendelin":{"pos":10,"name":"Wendelin","title":"der Wirt","startingCoins":5,"background":"Wendelin ist Herr über Krüge, Kasse und Hausrecht. Was an seinem Tisch passiert, entgeht ihm nicht.","character":"","traits":["Achtet darauf, dass alle versorgt sind.","Kommentiert gern das Geschehen am Tisch.","Sorgt für Ordnung, wenn es laut wird."],"ability":{"name":"Hausrecht","text":"Einmal im Spiel sieht Wendelin heimlich die nächste Ereigniskarte an und entscheidet, ob sie gespielt oder abgelegt wird. Spielt er sie, erhält er 1 Münze.","mechanic":"houseRules"},"task":{"name":"Volle Kasse","text":"Besitze am Ende mindestens 8 Münzen.","bonus":3}},"mathilda":{"pos":20,"name":"Mathilda","title":"die Mundschenkin","startingCoins":4,"background":"Mathilda kennt jeden Gast beim Namen und jedes Gerücht, das über den Tresen geht.","character":"","traits":["Aufmerksam und gesprächig.","Schenkt gern nach, auch Wasser.","Fragt die Leute neugierig aus."],"ability":{"name":"Trinkgeld","text":"Ab jetzt erhältst du für jede Ereigniskarte, die kein Minispiel ist, 1 Münze von der Bank. Kauft in dieser Zeit jemand eine geheime Ereigniskarte, erhältst du auch dafür 1 Münze. Das gilt, bis ein Minispiel gezogen wird.","mechanic":"tip"},"task":{"name":"Prost!","text":"Mache ein Foto, auf dem mindestens drei Gläser beim Anstoßen zu sehen sind.","bonus":2}},"torben":{"pos":30,"name":"Torben","title":"der Trunkenbold","startingCoins":3,"background":"Torben wirkt, als hätte er einen Krug zu viel gehabt. Aber er bekommt mehr mit, als alle denken. (Die Rolle wird nur gespielt, getrunken wird nicht mehr als sonst.)","character":"","traits":["Laut und gesellig.","Erzählt wirre Geschichten.","Verwechselt gern Namen."],"ability":{"name":"Glück des Narren","text":"Einmal im Spiel zieht Torben eine zufällige Belohnung von 1 bis 4 Münzen.","mechanic":"foolsLuck"},"task":{"name":"Geliehen ist geliehen","text":"Besitze am Ende einen Gegenstand, den dir ein Mitspieler freiwillig geliehen hat, ohne dass er ihn zurückverlangt hat. Der Besitzer bestätigt das.","bonus":3}},"klara":{"pos":40,"name":"Klara","title":"die Köchin","startingCoins":4,"background":"Aus Klaras Küche kommt die beste Suppe von ganz Valdrien. Wer einmal bei ihr gegessen hat, kommt wieder.","character":"","traits":["Spricht gern übers Essen.","Bietet anderen etwas an.","Hat zu allem ein Rezept."],"ability":{"name":"Stärkende Suppe","text":"Verliert Klara durch ein Ereignis Münzen, erhält sie einmal im Spiel direkt danach 3 Münzen.","mechanic":"heartySoup"},"task":{"name":"Geheimrezept","text":"Lege auf deinem Teller heimlich ein Gesicht aus Essen oder Besteck und fotografiere es.","bonus":2}},"severin":{"pos":50,"name":"Severin","title":"der Spielmann","startingCoins":4,"background":"Mit Laute und Liedern zieht Severin von Taverne zu Taverne. Wo er spielt, ist der Saal voll.","character":"","traits":["Summt vor sich hin.","Reimt gern.","Macht aus allem eine Geschichte."],"ability":{"name":"Zugabe","text":"Einmal im Spiel wählt Severin aus drei Minispielen eins aus und spielt mit. Gewinnt er, erhält er 2 zusätzliche Münzen.","mechanic":"encore"},"task":{"name":"Ohrwurm","text":"Nimm ein kurzes Video auf, in dem mindestens zwei Mitspieler gemeinsam singen oder summen. Nur mit ihrer Zustimmung.","bonus":3}},"fenja":{"pos":60,"name":"Fenja","title":"die Falschspielerin","startingCoins":3,"background":"Fenja lächelt freundlich, mischt geschickt und verliert erstaunlich selten.","character":"","traits":["Charmant und schlagfertig.","Will ständig wetten oder spielen.","Hat immer einen Trick auf Lager."],"ability":{"name":"Gezinkt","text":"Du lässt ein Minispiel wiederholen, egal ob du mitgespielt hast. Minispiel und Teilnehmer bleiben gleich. Der erste Versuch zählt nicht, Münzen werden erst nach dem zweiten Versuch verteilt. Der Knopf erscheint beim Minispiel, sobald deine Rolle erraten ist.","mechanic":"loadedDice"},"task":{"name":"Glückssträhne","text":"Gewinne mindestens zwei Minispiele.","bonus":3}},"hedda":{"pos":70,"name":"Hedda","title":"die Hellseherin","startingCoins":4,"background":"Hedda liest aus Teeblättern, Kerzenwachs und Bierschaum. Und manchmal liegt sie sogar richtig.","character":"","traits":["Geheimnisvoll.","Macht düstere Andeutungen.","»Spürt« Dinge, bevor sie passieren."],"ability":{"name":"Blick in die Zukunft","text":"Einmal im Spiel sieht Hedda heimlich die nächsten zwei Ereigniskarten und bestimmt, welche davon als Nächstes kommt.","mechanic":"foresight"},"task":{"name":"Prophezeiung","text":"Schreib zu Spielbeginn heimlich in dein Handy, wer am Ende die wenigsten Münzen hat. Stimmt es, hast du die Aufgabe erfüllt.","bonus":3}},"rudger":{"pos":80,"name":"Rudger","title":"der Raufbold","startingCoins":5,"background":"Rudger ist ein ehemaliger Söldner, der keinem Streit aus dem Weg geht. Zumindest keinem, den er gewinnen kann.","character":"","traits":["Großspurig.","Fordert gern andere heraus.","Kann schlecht verlieren."],"ability":{"name":"Herausforderung","text":"Du forderst einen Mitspieler deiner Wahl zum Duell. Gewinnst du, erhältst du die Hälfte seiner Münzen (aufgerundet). Verlierst du, erhält er die Hälfte deiner Münzen (aufgerundet).","mechanic":"challenge"},"task":{"name":"Ehrenhändel","text":"Gewinne mindestens ein Duell.","bonus":2}}},"minigames":{"muenzschieben":{"pos":10,"name":"Münzschieben","category":"duel","description":"Abwechselnd schiebt jeder eine Münze oder einen Bierdeckel mit einem Fingerschnipp über den Tisch. Wer näher an der Kante liegt, ohne herunterzufallen, gewinnt die Runde. Wer zuerst 2 Runden gewinnt, siegt.","reward":{"winner":2}},"daumenringen":{"pos":20,"name":"Daumenringen","category":"duel","description":"Verhakt die Finger, dann kämpfen die Daumen. Wer den Daumen des anderen drei Sekunden lang festhält, gewinnt.","reward":{"winner":2}},"pokerface":{"pos":30,"name":"Pokerface","category":"duel","description":"Jeder erzählt zwei wahre Dinge über sich und eins, das gelogen ist. Der andere muss die Lüge finden. Wer richtig liegt, bekommt einen Punkt. Bei Gleichstand wird wiederholt.","reward":{"winner":2}},"der-schnellste-griff":{"pos":40,"name":"Der schnellste Griff","category":"duel","description":"Ein Korken liegt zwischen euch. Ein Dritter sagt nacheinander Wörter. Bei »Prost!« wird gegriffen. Wer bei einem anderen Wort zugreift, verliert sofort.","reward":{"winner":2,"loser":-1}},"die-gefuehlte-minute":{"pos":50,"name":"Die gefühlte Minute","category":"all","description":"Alle schließen die Augen. Wer glaubt, dass genau eine Minute vergangen ist, hebt die Hand. Einer stoppt mit dem Handy. Wer am nächsten dran ist, gewinnt.","reward":{"winner":2}},"ein-wort-eine-geschichte":{"pos":60,"name":"Ein Wort, eine Geschichte","category":"all","description":"Reihum sagt jeder ein Wort, gemeinsam entsteht eine Geschichte. Wer zögert, lacht oder einen Satz kaputtmacht, scheidet aus. Der Letzte gewinnt.","reward":{"winner":3}},"der-tresenturm":{"pos":70,"name":"Der Tresenturm","category":"all","description":"Jeder baut in einer Minute einen Turm aus Dingen auf dem Tisch, aber ohne Essen und ohne volle Gläser. Der höchste Turm, der noch steht, gewinnt.","reward":{"winner":2}},"maerchengestalt":{"pos":80,"name":"Märchengestalt","category":"all","description":"Einer denkt an eine Figur aus Märchen oder Sagen, die anderen stellen reihum Ja-Nein-Fragen. Wer sie errät, gewinnt. Nach 20 Fragen ohne Treffer gewinnt der, der sie sich ausgedacht hat.","reward":{"winner":2}},"das-schweigende-mahl":{"pos":90,"name":"Das schweigende Mahl","category":"all","description":"Ab jetzt wird nicht mehr gesprochen. Wer redet oder laut lacht, scheidet aus. Grimassen sind erlaubt. Der Letzte gewinnt.","reward":{"winner":2}},"seemannsgarn":{"pos":100,"name":"Seemannsgarn","category":"oneVsAll","description":"Der Einzelne erzählt drei kurze Geschichten aus seinem Leben, eine davon ist erfunden. Die Gruppe einigt sich, welche gelogen ist. Liegt sie richtig, gewinnt die Gruppe.","reward":{"solo":3,"group":1}},"das-gedaechtnis-des-wirts":{"pos":110,"name":"Das Gedächtnis des Wirts","category":"oneVsAll","description":"Der Einzelne prägt sich 20 Sekunden lang den Tisch ein und dreht sich um. Die Gruppe verändert zwei Dinge. Er muss beide finden.","reward":{"solo":3,"fail":-1}},"das-huetchenspiel":{"pos":120,"name":"Das Hütchenspiel","category":"oneVsAll","description":"Der Einzelne versteckt einen Kronkorken unter einem von drei Bechern und mischt. Die Gruppe einigt sich auf einen Becher. Drei Runden. Trifft die Gruppe mindestens zweimal, gewinnt sie.","reward":{"solo":3,"group":1}},"pantomime-der-taverne":{"pos":130,"name":"Pantomime der Taverne","category":"team","description":"Abwechselnd stellt ein Spieler etwas aus der Taverne pantomimisch dar, zum Beispiel Bierzapfen, eine Schlägerei oder einen Betrunkenen auf der Treppe. Sein Team hat 30 Sekunden zum Raten. Nach drei Runden pro Team gewinnt das Team mit mehr Treffern.","reward":{"team":1}},"die-speisekarte":{"pos":140,"name":"Die Speisekarte","category":"team","description":"Die Teams nennen abwechselnd ein Gericht oder Getränk. Wer nicht weiterweiß oder etwas wiederholt, verliert.","reward":{"team":1}},"der-rausschmeisser":{"pos":150,"name":"Der Rausschmeißer","category":"uneven","description":"Der Rausschmeißer nennt in 30 Sekunden so viele Reime auf »Krug« wie möglich, zum Beispiel klug, Zug, genug. Danach haben die zwei Gäste zusammen 30 Sekunden für Reime auf »Wein«. Wer mehr schafft, gewinnt.","reward":{"single":3,"pair":2,"singleName":"Rausschmeißer","pairName":"Gäste"}}},"events":{"lokalrunde":{"pos":10,"name":"Lokalrunde","category":"Segen","visibility":"public","description":"Der Wirt gibt einen aus! Alle stoßen an, Wasser zählt genauso, und erhalten 1 Münze.","effect":"goldRain"},"die-zeche-wird-faellig":{"pos":20,"name":"Die Zeche wird fällig","category":"Fluch","visibility":"public","description":"Der Wirt kommt mit der Rechnung. Alle zahlen 1 Münze an die Spielbank. Wer keine hat, kommt davon.","effect":"tax"},"anschreiben-lassen":{"pos":30,"name":"Anschreiben lassen","category":"Segen","visibility":"public","description":"Der Wirt hat ein Herz für arme Schlucker. Wer die wenigsten Münzen hat, erhält 3 Münzen. Bei Gleichstand sind alle Gleichplatzierten betroffen.","effect":"favor"},"kneipenschlaegerei":{"pos":40,"name":"Kneipenschlägerei","category":"Duell","visibility":"public","description":"Ein falsches Wort, und schon fliegen die Fäuste. Wer die meisten und wer die wenigsten Münzen hat, treten in einem Minispiel gegeneinander an. Der Sieger erhält von jedem Verlierer 2 Münzen. Bei Gleichstand sind alle Gleichplatzierten betroffen. Sie treten alle mit an.","effect":"duel"},"ein-taschendieb-geht-um":{"pos":50,"name":"Ein Taschendieb geht um","category":"Fluch","visibility":"public","description":"Im Gedränge am Tresen verschwindet ein Geldbeutel. Wer die meisten Münzen hat, verliert 2 Münzen an die Spielbank. Bei Gleichstand sind alle Gleichplatzierten betroffen.","effect":"pickpocket"},"gerede-am-tresen":{"pos":60,"name":"Gerede am Tresen","category":"Fluch","visibility":"public","description":"Die Leute tuscheln über euch. Alle, deren Rolle schon erraten wurde, verlieren 1 Münze.","effect":"exposed","requiresRoles":true},"inkognito":{"pos":70,"name":"Inkognito","category":"Segen","visibility":"public","description":"Wer unerkannt bleibt, hat es leichter. Alle, deren Rolle noch nicht erraten wurde, erhalten 1 Münze.","effect":"disguise","requiresRoles":true},"tisch-gegen-tisch":{"pos":80,"name":"Tisch gegen Tisch","category":"Team gegen Team","visibility":"public","description":"Die Entdeckten, deren Rolle erraten wurde, treten als Team gegen die Unentdeckten an. Jeder im Siegerteam erhält 1 Münze. Gibt es nur ein Lager, wird ein Alle-gegen-alle daraus, und der Sieger erhält 2 Münzen.","effect":"camps","requiresRoles":true},"der-spielmann-fordert-zum-wettstreit":{"pos":90,"name":"Der Spielmann fordert zum Wettstreit","category":"Alle gegen alle","visibility":"public","description":"Severin stimmt ein Lied an und ruft zum Wettstreit. Zieht ein Minispiel, bei dem alle gegeneinander antreten. Der Gewinner erhält die doppelte Belohnung.","effect":"contest"},"ein-fremder-tritt-ein":{"pos":100,"name":"Ein Fremder tritt ein","category":"Einer gegen alle","visibility":"public","description":"Ein Fremder im nassen Mantel setzt sich an euren Tisch und fordert den Reichsten heraus. Wer die meisten Münzen hat, tritt allein gegen alle an. Gewinnt er, erhält er 3 Münzen. Gewinnt die Gruppe, erhalten alle anderen je 1 Münze. Bei Gleichstand sind alle Gleichplatzierten betroffen. Sie treten gemeinsam an.","effect":"stranger"},"grosszuegigkeit-des-reichen":{"pos":110,"name":"Großzügigkeit des Reichen","category":"Entscheidung","visibility":"public","description":"Alle Augen richten sich auf den, der am meisten hat. Wer die meisten Münzen hat, wählt: Entweder schenkt er einem Mitspieler seiner Wahl 2 Münzen, oder er zahlt 3 Münzen an die Spielbank. Bei Gleichstand sind alle Gleichplatzierten betroffen. Jeder entscheidet für sich.","effect":"generosity"},"das-spiel-des-schicksals":{"pos":120,"name":"Das Spiel des Schicksals","category":"Glück","visibility":"public","description":"Ein alter Mann zieht eine Münze aus der Tasche und lässt sie für jeden von euch tanzen. Die App wirft für jeden eine Münze. Kopf: +1 Münze. Zahl: −1 Münze.","effect":"fate"},"lose-zungen":{"pos":130,"name":"Lose Zungen","category":"Segen, hält an","visibility":"public","description":"Der Abend wird lang, und die Zungen werden locker. Bis zum nächsten Ereignis kostet Raten keine Münze.","effect":"looseTongues","requiresRoles":true},"ein-gemuetlicher-abend":{"pos":140,"name":"Ein gemütlicher Abend","category":"Ruhe","visibility":"public","description":"Nichts geschieht. Das Feuer knistert, die Suppe dampft, und draußen heult der Sturm.","effect":"calm"},"der-hund-des-wirts":{"pos":150,"name":"Der Hund des Wirts","category":"Ruhe","visibility":"public","description":"Ein alter Hund trottet durch die Stube, schnüffelt an jedem Stuhl und legt sich vor den Kamin. Nichts geschieht.","effect":"calm"}}},"dungeon":{"pos":30,"name":"Das Henkersmahl im Verlies","setting":"Drinnen am Tisch · Halloween-Abenteuer: düster, gruselig und derb","goal":"keys","story":{"title":"Das Henkersmahl im Verlies","paragraphs":["Tief unter Burg Schwarzfels, wo kein Licht hinkommt und die Ratten Namen haben, sitzt ihr in Ketten. Warum? Jeder von euch schwört, er sei unschuldig. Natürlich.","Einmal im Jahr, in der Nacht der Toten, dürfen die Gefangenen ihre Zellen verlassen und gemeinsam essen: das Henkersmahl. Ihr sitzt im Gemeinschaftsraum des Verlieses an einem langen, wackeligen Tisch. Der Eintopf ist grau, das Bier ist warm, und was da im Brot knirscht, will niemand so genau wissen. Die Wachen sind oben beim Fest, nur der alte Kerkermeister ist geblieben. Er sitzt mit am Tisch, und er trinkt mit. Krug um Krug.","Nach oben führt kein Weg hinaus. Dort feiern die Wachen in der großen Halle, und an ihnen kommt niemand vorbei. Der einzige Ausweg führt nach unten. Unter dem Verlies liegen die alten Katakomben, ein Labyrinth aus Gängen und Grabkammern, in das seit Jahrhunderten niemand mehr freiwillig hinabsteigt. Ganz am Ende der Katakomben, so erzählt man sich, mündet ein uralter Abflusstunnel in den Burggraben.","Der Weg dorthin führt durch drei Türen. Zuerst die rostige Eisentür, die vom Gemeinschaftsraum hinaus in den finsteren Wachgang führt. Am Ende des Gangs das Silbergitter, hinter dem eine schmale Wendeltreppe tief hinab in die Katakomben führt. Es ist aus Silber geschmiedet, damit nichts heraufkommt, was dort unten haust. Und am Ende der Katakomben, wo die Luft nach Moder und Grabwasser riecht, das Knochentor. Es ist gebaut aus den Gebeinen all jener, die es nicht hinausgeschafft haben. Dahinter liegt der Tunnel, und dahinter die Freiheit.","Die Schlüssel hängen alle am Gürtel des Kerkermeisters, ein riesiger, klirrender Bund. Eisenschlüssel hat er viele, Silberschlüssel schon weniger, und Knochenschlüssel nur eine Handvoll. Wer einen davon erwischt, hat Glück. Und der Kerkermeister ist bestechlich. Noch ist er fast nüchtern, beißt auf jede Münze und lässt sich seine Schlüssel teuer bezahlen. Aber die Nacht ist lang, das Fass unter dem Tisch ist voll, und mit jedem Krug wird er großzügiger. Welcher Schlüssel welcher ist, weiß er allerdings schon jetzt nicht mehr. Wer ihm Münzen zuschiebt, bekommt einen Schlüssel, irgendeinen.","Zu Beginn kostet ein Schlüssel 7 Münzen. Jedes Mal, wenn der Kerkermeister ein Stück betrunkener wird, sinkt der Preis um 1 Münze, bis er am Ende für 2 Münzen alles hergibt, was an seinem Gürtel klimpert. Bei jedem Kauf bekommt ihr zufällig einen Schlüssel: Eisen oft, Silber seltener, Knochen selten. Welche Schlüssel ihr habt, weiß nur jeder selbst. Wer drei verschiedene Schlüssel besitzt, öffnet Eisentür, Silbergitter und Knochentor, flieht durch die Katakomben und bricht aus.","Wer hinauswill, muss also kaufen, bis er alle drei beisammen hat. Früh kaufen ist teuer, warten ist gefährlich."],"closing":"Und das schnell, denn im Morgengrauen kommt der Henker, und er hat heute eine lange Liste."},"epilogue":{"title":"Der Ausbruch","before":["Der Kerkermeister schnarcht mit dem Kopf im Eintopf. Leise dreht sich ein Schlüssel in der Eisentür, dann einer im Silbergitter. Schritte hallen die Wendeltreppe hinab, und tief unten in den Katakomben knirscht das Knochentor. Draußen dämmert der Morgen, und ein einziger Schatten kriecht aus dem Tunnel in den Burggraben:"],"after":["{winner} ist frei! Die anderen Gefangenen sitzen noch beim kalten Eintopf und probieren den zwölften Schlüssel an der Eisentür, als schwere Schritte die Treppe herunterkommen. Der Henker ist da, und er hat seine Liste dabei. Ein Name ist durchgestrichen."]},"terms":{"question":"Wer sitzt mit am Henkersmahl?","player":"Gefangener","plural":"Gefangene","dative":"Gefangenen","finish":"Der Henker kommt"},"roles":{"wolfram-der-werwolf":{"pos":10,"name":"Wolfram","title":"der Werwolf","startingCoins":3,"background":"Wolfram ist Schweinehirt im Dorf unter der Burg, ein gutmütiger Kerl mit sehr viel Bart. Nur bei Vollmond wird er ein bisschen haariger. Beim Erntefest ging der Mond genau in dem Moment auf, als das Spanferkel des Burgherrn am Spieß drehte. Am Morgen wachte Wolfram nackt im Hühnerstall auf, ein Schweineohr im Mund und Federn an Stellen, die man nicht nennen will. Angeklagt wegen Spanferkelraubs und unsittlicher Entblößung. Er schwört, er ist unschuldig: Das war der Wolf.","character":"Schnupper an deinem Essen, bevor du isst, und ab und zu unauffällig an deinem Nachbarn.\nKratz dich hinter dem Ohr oder am Hals, als würde es dort jucken.\nFrag hin und wieder: „Ist heute eigentlich Vollmond?“\nÜbertreib es nicht: Ein kurzes Heulen am Abend reicht.","traits":["ist der Werwolf aus dem Dorf","schnuppert an Essen und Mitspielern","kratzt sich ständig hinter dem Ohr"],"ability":{"name":"Goldfinger","text":"Direkt nachdem du ein Minispiel gewonnen hast, verdoppelst du deinen Gewinn.","mechanic":"goldFinger"}},"roderick-der-ritter":{"pos":20,"name":"Roderick","title":"der Ritter","startingCoins":3,"background":"Roderick ist ein fahrender Ritter mit verbeulter Rüstung und unverbeulter Ehre. Er rettet jede Dame, ob sie will oder nicht. Beim Fest oben sah er im Turmfenster eine Dame in Not, kletterte die Burgmauer hoch und warf sie sich über die Schulter. Es war die Schwiegermutter des Burgherrn, die nur Luft schnappen wollte. Sie zog ihm den Nachttopf über, er fiel in den Misthaufen und von dort direkt ins Verlies. Bei seiner Ehre: Er ist unschuldig. Sie hat sehr wohl „Hilfe!“ gerufen. Allerdings erst, als sie ihn sah.","character":"Sag oft „Bei meiner Ehre!“ und leg dabei die Hand aufs Herz.\nKündige vor Minispielen deinen Sieg an, als wäre es ein Turnier.\nVerbeug dich, wenn dir jemand etwas reicht.","traits":["ist ein fahrender Ritter","schwört „Bei meiner Ehre!“","kündigt vor Minispielen seinen Sieg an"],"ability":{"name":"Das Turnier","text":"Sobald ein Minispiel gezogen wurde, bei dem du mitspielst, und Regeln und Gegner feststehen, kündigst du deinen Sieg an. Gewinnst du, erhältst du zusätzlich zu deinem Gewinn 1 Münze von jedem Mitspieler des Minispiels. (Info: Bei jedem Minispiel, bei dem du mitspielst, erscheint vor dem Start ein Knopf, mit dem du die Fähigkeit aktivierst.)","mechanic":"marksman"}},"zacharias-der-zocker":{"pos":30,"name":"Zacharias","title":"der Zocker","startingCoins":3,"background":"Zacharias ist Spieler aus Leidenschaft und pleite aus Gewohnheit. Er hat schon Haus, Hof und einen Backenzahn verwettet. Beim Fest oben würfelte er gegen den Burgvogt und verlor alles: Geld, Pferd, Hose. Dann setzte er die Burg selbst, die ihm nicht gehörte, und gewann. Als er die Schlüssel abholen wollte, bekam er nur einen einzigen: den zu Zelle sieben. Er schwört, er ist unschuldig. Gewonnen ist gewonnen.","character":"Sag „Alles oder nichts!“, wann immer es um Münzen geht.\nLass eine Münze, einen Korken oder Kronkorken über deine Finger wandern oder klimpere damit.\nErzähl, dass du heute eine Glückssträhne spürst.","traits":["ist ein Zocker","sagt „Alles oder nichts!“","spielt ständig mit einer Münze oder einem Korken"],"ability":{"name":"Glücksfee","text":"Du wählst Kopf oder Zahl, und die App wirft eine Münze. Liegst du richtig, nimmst du dem reichsten Mitspieler die Hälfte seiner Münzen weg (aufgerundet). Bist du selbst der Reichste, trifft es den Zweitreichsten. Bei Gleichstand wählst du einen davon aus. Liegst du falsch, verlierst du alle deine Münzen an die Bank.","mechanic":"luckyFairy"}},"magnus-der-mundschenk":{"pos":40,"name":"Magnus","title":"der Mundschenk","startingCoins":3,"background":"Magnus ist Mundschenk des Burgherrn und nimmt seinen Beruf sehr ernst. Seine wichtigste Pflicht: jeden Becher vorkosten, damit niemand den Herrn vergiftet. Beim Herbstbankett kostete er so gründlich vor, dass für den Burgherrn nur ein leeres Fass blieb und Magnus singend unter der Tafel lag, die Hose auf dem Kopf. Angeklagt wegen Veruntreuung von zwölf Fässern Wein. Er schwört, er ist unschuldig: Es hätte ja Gift drin sein können.","character":"Schenk deinen Mitspielern nach, ob sie wollen oder nicht. Wasser zählt genauso, und niemand muss trinken.\nBring Trinksprüche aus, zum Beispiel: „Auf den Kerkermeister, möge er nie nüchtern werden!“\nPrüf jedes Getränk mit einem kleinen Schluck und einem Kennerblick.","traits":["ist der Mundschenk des Burgherrn","schenkt allen nach","bringt Trinksprüche aus"],"ability":{"name":"Trinkgeld","text":"Ab jetzt erhältst du für jede Ereigniskarte, die kein Minispiel ist, 1 Münze von der Bank. Kauft in dieser Zeit jemand eine geheime Ereigniskarte, erhältst du auch dafür 1 Münze. Das gilt, bis ein Minispiel gezogen wird.","mechanic":"tip"}},"hilda-die-hexe":{"pos":50,"name":"Hilda","title":"die Hexe","startingCoins":3,"background":"Hilda ist Kräuterweib, Hebamme und Fluchexpertin aus dem Moor. Sie verkauft Liebestränke, Warzensalbe und Flüche nach Maß. Auf dem Herbstmarkt kaufte der Burgvogt einen Liebestrank für die Wirtin. Leider trank er ihn selbst, und leider stand gerade sein Ziegenbock daneben. Die beiden sind seitdem unzertrennlich, und Hilda sitzt wegen Hexerei. Sie schwört, sie ist unschuldig: Auf der Flasche stand groß „Nicht selbst trinken!“.","character":"Murmle leise Flüche und Zaubersprüche vor dich hin, gern gereimt.\nRühr in deinem Becher oder auf deinem Teller immer gegen den Uhrzeigersinn.\nKicher, wenn jemandem ein Missgeschick passiert: „Das war ich nicht. Vielleicht.“","traits":["ist eine Hexe aus dem Moor","murmelt Flüche und Zaubersprüche","rührt gegen den Uhrzeigersinn"],"ability":{"name":"Gezinkt","text":"Du lässt ein Minispiel wiederholen, egal ob du mitgespielt hast. Minispiel und Teilnehmer bleiben gleich. Der erste Versuch zählt nicht, Münzen werden erst nach dem zweiten Versuch verteilt. Der Knopf erscheint beim Minispiel, sobald deine Rolle erraten ist.","mechanic":"loadedDice"}},"vlad-der-vampir":{"pos":60,"name":"Vlad","title":"der Vampir","startingCoins":3,"background":"Vlad ist ein Graf aus dem fernen Osten: sehr blass, sehr höflich und sehr durstig. Er reiste zum Fest auf Burg Schwarzfels, weil man ihm ein blutiges Steak versprochen hatte. Es kam durchgebraten. Enttäuscht biss er stattdessen der Gräfin in den Hals. Die Gräfin fand es aufregend, der Graf weniger. Jetzt sitzt Vlad hier unten, wo es endlich schön dunkel ist. Er schwört, er ist unschuldig: Er wollte ihr nur etwas ins Ohr flüstern und ist abgerutscht.","character":"Halt dir die Serviette wie einen Umhang vors Gesicht, wenn dich jemand ansieht.\nStarr ab und zu verträumt auf den Hals deines Nachbarn.\nMeide Licht: Rück von Kerzen und Lampen ab oder schirm deine Augen ab.","traits":["ist ein Vampirgraf aus dem Osten","starrt auf Hälse","versteckt sich hinter der Serviette wie hinter einem Umhang"],"ability":{"name":"Herausforderung","text":"Du forderst einen Mitspieler deiner Wahl zum Duell. Gewinnst du, erhältst du die Hälfte seiner Münzen (aufgerundet). Verlierst du, erhält er die Hälfte deiner Münzen (aufgerundet).","mechanic":"challenge"}},"dietrich-der-dieb":{"pos":70,"name":"Dietrich","title":"der Dieb","startingCoins":3,"background":"Dietrich ist Taschendieb, Einbrecher und Hühnerdieb, je nach Tageszeit. Er hat flinke Finger und ein ehrliches Gesicht, das macht die Sache leichter. Beim Fest oben ließ er die Silberlöffel des Burgherrn mitgehen, alle achtundvierzig, versteckt in seiner Hose. Auf dem Weg hinaus klimperte er wie ein Glockenspiel, und die Wache tanzte noch eine Runde mit ihm, bevor sie ihn festnahm. Er schwört, er ist unschuldig: Die Löffel sind ihm von selbst in die Hose gefallen.","character":"Lass harmlose Kleinigkeiten vom Tisch mitgehen: Korken, Bierdeckel, Servietten. Nichts Wertvolles, kein Handy, kein Geld, keine Schlüssel.\nBeteuere bei jeder Gelegenheit: „Ich hab nichts genommen!“\nTast immer wieder deine Taschen ab, als würdest du nachzählen.","traits":["ist ein Dieb","lässt Kleinigkeiten vom Tisch mitgehen","beteuert „Ich hab nichts genommen!“"],"ability":{"name":"Langfinger","text":"Du wählst bis zu drei verschiedene Mitspieler und drehst für jeden einmal am Glücksrad. Das Rad hat vier gleich große Felder: −1, +1, +2 und +3. Bei einem Plus nimmst du diesem Mitspieler so viele Münzen weg. Bei −1 hat er dich beim Klauen erwischt, und du gibst ihm 1 Münze.","mechanic":"longFingers"}},"heinrich-der-harnharte":{"pos":80,"name":"Heinrich","title":"der Harnharte","startingCoins":3,"background":"Heinrich ist ein geselliger Bürger mit sehr großem Durst und sehr kleiner Blase. Er war als Gast zum Fest oben in der Burg eingeladen. Nach dem dritten Krug musste er mal, wie immer. Die Abtritte waren besetzt, also stellte er sich in den Burghof und erleichterte sich ausgiebig an die Burgmauer. Leider genau unter dem Fenster des Burgherrn, der gerade frische Luft schnappen wollte. Jetzt sitzt Heinrich wegen „Beschmutzung herrschaftlichen Gemäuers“ im Verlies und schwört, er sei unschuldig. Die Mauer hätte schließlich im Weg gestanden.","character":"Sag immer wieder: „Ich muss mal wieder.“\nFrag in die Runde: „Muss noch wer?“\nRutsch unruhig auf deinem Platz herum, wenn es spannend wird.","traits":["war Gast beim Fest oben","muss ständig mal","fragt, ob noch wer muss"],"ability":{"name":"Pinkelpause","text":"Direkt nachdem eine Ereigniskarte gezogen wurde, kannst du aussetzen. Diese und alle weiteren Ereigniskarten gelten dann nicht für dich, bis du wieder einsteigst. Für jede am Stück ausgesetzte Ereigniskarte erhältst du 1 Münze von der Bank (höchstens 10). Sobald deine Rolle erraten ist, erscheint bei jeder Ereigniskarte ein Knopf zum Aussetzen und Wiedereinsteigen.","mechanic":"bathroomBreak"}},"gregor-der-gelehrte":{"pos":90,"name":"Gregor","title":"der Gelehrte","startingCoins":3,"background":"Gregor ist Medicus, Sterndeuter und Leichenaufschneider, alles im Namen der Wissenschaft. Er weiß viel und erzählt noch mehr. Als der Hofnarr der Burg starb, wollte Gregor endlich herausfinden, wo bei einem Narren der Witz sitzt. Er schlich nachts in die Gruft und schnitt nach. Den Witz fand er nicht, dafür fand ihn die Witwe des Narren. Jetzt sitzt er wegen Grabschändung hier und schwört, er ist unschuldig: Der Narr hätte es lustig gefunden.","character":"Fang Sätze an mit „Wusstet ihr eigentlich …?“ und erzähl dann eine Kerkerweisheit, gern erfunden.\nSag „Faszinierend!“, wenn etwas Ekliges oder Seltsames passiert.\nFrag die anderen neugierig nach den Einzelheiten ihrer Verbrechen.","traits":["ist ein Gelehrter und Medicus","beginnt Sätze mit „Wusstet ihr eigentlich …?“","sagt „Faszinierend!“"],"ability":{"name":"Neugiernase","text":"Du stellst einem Mitspieler heimlich eine Ja-Nein-Frage zu seiner Rolle, und er muss ehrlich antworten. Nach dem Rollennamen selbst darfst du nicht fragen. Errätst du seine Rolle später, erhältst du für den Treffer 6 statt 3 Münzen.","mechanic":"curiosity"}},"gunther-der-gaukler":{"pos":100,"name":"Gunther","title":"der Gaukler","startingCoins":3,"background":"Gunther ist Gaukler, Feuerspucker und Witzeerzähler, wobei die Witze das Gefährlichste sind. Er sollte beim Fest den Burgherrn zum Lachen bringen. Er jonglierte mit drei Fackeln, verbrannte sich nur ein bisschen und erzählte dann den Witz über die Burgherrin und den Stallknecht. Der ganze Saal lachte. Nur der Burgherr nicht, und der Stallknecht auch nicht. Gunther schwört, er ist unschuldig: Woher sollte er wissen, dass der Witz wahr ist?","character":"Ruf „Tadaa!“, wenn dir etwas gelingt, und sei es nur, dass du dein Glas abstellst.\nErzähl schlechte Witze und lach selbst am lautesten.\nMach kleine Kunststückchen: einen Löffel balancieren, einen Korken verschwinden lassen.","traits":["ist ein Gaukler","ruft „Tadaa!“","erzählt schlechte Witze"],"ability":{"name":"Narrenrätsel","text":"Du wählst heimlich eine Zahl: 2, 4 oder 6. Ein Mitspieler deiner Wahl rät sie. Liegt er falsch, erhältst du so viele Münzen von der Bank. Liegt er richtig, erhält er die Hälfte der Zahl von der Bank.","mechanic":"foolsRiddle"}}},"minigames":{"die-henkersgrimasse":{"pos":10,"name":"Die Henkersgrimasse","category":"duel","description":"Ihr schaut euch über den Tisch in die Augen. Abwechselnd schneidet ihr die grausigste Fratze, die ihr könnt, jeder dreimal. Wer zuerst lacht oder grinst, verliert. Lacht keiner, gewinnt die gruseligere Fratze, darüber entscheidet die Gruppe per Handzeichen.","reward":{"winner":3}},"der-loeffel-am-galgen":{"pos":20,"name":"Der Löffel am Galgen","category":"duel","description":"Jeder hängt sich einen Löffel an die Nase. Auf „Los!“ zählt die Gruppe laut die Sekunden. Wessen Löffel länger hängen bleibt, gewinnt. Wer ihn mit der Hand berührt, verliert sofort. Jeder hat drei Versuche, der längste zählt.","reward":{"winner":3}},"das-letzte-wort":{"pos":30,"name":"Das letzte Wort","category":"duel","description":"Ihr nennt abwechselnd ein gruseliges Wort: Sarg, Galgen, Nebel, Leiche … Jedes neue Wort muss mit dem letzten Buchstaben des vorigen beginnen. Wer länger als fünf Sekunden zögert oder ein Wort wiederholt, verliert. Ob ein Wort gruselig genug ist, entscheidet die Gruppe.","reward":{"winner":3}},"der-beste-kerkermeister":{"pos":40,"name":"Der beste Kerkermeister","category":"duel","description":"Wer kann den betrunkenen Kerkermeister besser? Jeder hat zehn Sekunden: lallen, schwanken, den richtigen Schlüssel suchen, ein Lied anstimmen. Der Herausforderer beginnt. Danach stimmt die Gruppe per Handzeichen ab. Bei Gleichstand gibt es eine zweite Runde mit fünf Sekunden.","reward":{"winner":3}},"die-henkersmahlzeit":{"pos":50,"name":"Die Henkersmahlzeit","category":"all","description":"Jeder beschreibt in einem Satz seine letzte Mahlzeit vor dem Galgen, so köstlich oder so eklig, wie er will. Der Richter spielt den Kerkermeister, hört sich alles an und kürt das beste Henkersmahl. Sein Wort gilt.","reward":{"winner":3,"judge":1}},"stellt-euch-tot":{"pos":60,"name":"Stellt euch tot","category":"all","description":"Auf Kommando stirbt jeder einen dramatischen Tod und bleibt danach regungslos auf seinem Platz. Wer sich bewegt, lacht oder spricht, ist raus. Die Ausgeschiedenen dürfen die Übrigen mit Grimassen und Gruselgeräuschen zum Lachen bringen, aber niemanden anfassen. Wer zuletzt noch tot ist, gewinnt.","reward":{"winner":3}},"das-rattenrennen":{"pos":70,"name":"Das Rattenrennen","category":"all","description":"Stellt ein Glas als Käse in die Tischmitte. Jeder legt einen Korken oder Kronkorken als Ratte an die Tischkante vor sich. Reihum schnippt jeder seine Ratte zweimal in Richtung Käse. Wessen Ratte am Ende am nächsten am Käse liegt, gewinnt. Ratten, die vom Tisch fallen, sind tot. Bei Streit entscheidet die Gruppe.","reward":{"winner":3}},"das-monsterverzeichnis":{"pos":80,"name":"Das Monsterverzeichnis","category":"all","description":"Reihum nennt jeder ein Ungeheuer, eine Spukgestalt oder ein Gruselwesen: Vampir, Ghul, Schwiegermutter … Wer länger als fünf Sekunden zögert oder etwas wiederholt, ist raus. Wer zuletzt übrig bleibt, gewinnt. Ob etwas zählt, entscheidet die Gruppe per Handzeichen.","reward":{"winner":3}},"wer-hat-den-schluessel":{"pos":90,"name":"Wer hat den Schlüssel?","category":"oneVsAll","description":"Der Einzelne spielt den Kerkermeister und schließt die Augen. Die anderen geben unter dem Tisch einen Korken als Schlüssel herum, bis jemand „Fertig!“ ruft. Dann legen alle beide Fäuste auf den Tisch. Der Kerkermeister darf so oft raten, wie halb so viele Gefangene mitspielen (aufgerundet); jede Faust, auf die er zeigt, öffnet sich. Findet er den Schlüssel, gewinnt er, sonst gewinnt die Gruppe.","reward":{"solo":4,"group":1}},"das-verhoer":{"pos":100,"name":"Das Verhör","category":"oneVsAll","description":"Die Gruppe verhört den Einzelnen eine Minute lang mit schnellen Fragen. Er muss jede Frage beantworten, darf aber nie „Ja“ oder „Nein“ sagen, auch nicht „Jo“, „Nö“ oder nicken. Hält er die ganze Minute durch, gewinnt er. Rutscht ihm ein Ja oder Nein heraus, gewinnt die Gruppe. Die Zeit nimmt jemand mit dem Handy.","reward":{"solo":4,"group":1}},"zehn-ausreden":{"pos":110,"name":"Zehn Ausreden","category":"oneVsAll","description":"Der Einzelne hat eine Minute Zeit, zehn verschiedene Ausreden zu nennen, warum er völlig unschuldig im Verlies sitzt. Die Gruppe zählt laut mit, Wiederholungen zählen nicht. Schafft er zehn, gewinnt er. Sonst scheitert er. Bei Streit entscheidet die Gruppe per Handzeichen.","reward":{"solo":4,"fail":-1}},"galgenmaennchen":{"pos":120,"name":"Galgenmännchen","category":"team","description":"Jedes Team denkt sich heimlich ein gruseliges Wort aus (Katakombe, Henkersmahl, Moder …) und nennt nur die Anzahl der Buchstaben. Abwechselnd raten die Teams einen Buchstaben im Wort der anderen. Jeder Fehlversuch bringt das ratende Team eine Stufe näher an den Galgen; zählt laut mit oder malt auf eine Serviette. Wer zuerst das ganze Wort der anderen errät, gewinnt. Nach acht Fehlversuchen hängt das Team und verliert.","reward":{"team":2}},"kerkerfluesterpost":{"pos":130,"name":"Kerkerflüsterpost","category":"team","description":"Jedes Team bekommt vom anderen Team einen gruseligen Satz mit mindestens acht Wörtern, geflüstert an die erste Person. Im Team wird der Satz von Ohr zu Ohr weitergeflüstert, jeder flüstert nur einmal. Die letzte Person sagt laut, was angekommen ist. Das Team, bei dem mehr Wörter richtig angekommen sind, gewinnt. Ist ein Team nur eine Person, hört sie den Satz einmal und wiederholt ihn.","reward":{"team":2}},"galgen-beil-und-gift":{"pos":140,"name":"Galgen, Beil und Gift","category":"uneven","description":"Wie Schere, Stein, Papier: Das Beil (Handkante) zerhackt den Galgen, der Galgen (flache Hand) schlägt das Gift, das Gift (Faust als Fläschchen) schlägt das Beil, denn der Henker kippt vorher um. Der Henker spielt gleichzeitig gegen beide Verurteilten. Auf „Eins, zwei, drei, tot!“ zeigen alle drei ihr Zeichen. Der Henker bekommt einen Punkt für jeden Verurteilten, den er schlägt, die Verurteilten bekommen einen Punkt für jedes Mal, das einer von ihnen den Henker schlägt. Wer zuerst fünf Punkte hat, gewinnt.","reward":{"single":4,"pair":2,"singleName":"Henker","pairName":"Verurteilten"}},"die-dreizehnte-stufe":{"pos":150,"name":"Die dreizehnte Stufe","category":"uneven","description":"Der Galgen hat dreizehn Stufen. Ihr zählt laut von eins aufwärts, immer in dieser Reihenfolge: Kerkermeister, erster Ausbrecher, Kerkermeister, zweiter Ausbrecher. Wer dran ist, sagt eine, zwei oder drei Zahlen hintereinander. Wer die Dreizehn sagen muss, verliert die Runde. Gespielt wird, bis eine Seite zwei Runden gewonnen hat.","reward":{"single":4,"pair":2,"singleName":"Kerkermeister","pairName":"Ausbrecher"}}},"events":{"das-seilgeld":{"pos":20,"name":"Das Seilgeld","category":"Fluch","visibility":"public","description":"Ein Bote des Henkers poltert herein: Jeder Gefangene zahlt seinen Anteil am Seil, gutes Hanfseil ist teuer. Alle zahlen 1 Münze an die Spielbank.","effect":"tax","requiresRoles":false,"drinking":false},"gustav-hat-hunger":{"pos":40,"name":"Gustav hat Hunger","category":"Fluch","visibility":"public","description":"Gustav, die fetteste Ratte des Verlieses, nagt sich durch den dicksten Geldbeutel am Tisch. Wer die meisten Münzen hat, verliert 2 Münzen. Bei Gleichstand trifft es alle Gleichplatzierten.","effect":"pickpocket","requiresRoles":false,"drinking":false},"peinliche-befragung":{"pos":60,"name":"Der Henker merkt sich Gesichter","category":"Enthüllung","visibility":"public","description":"Der Henker steigt die Wendeltreppe herab und mustert jeden Gefangenen ganz genau. Wessen wahre Identität schon erraten wurde, der landet nach einem Ausbruch für immer auf den Fahndungsplakaten des ganzen Landes, außer er zahlt dem Henker etwas für sein schlechtes Gedächtnis. Alle, deren Rolle erraten wurde, zahlen 1 Münze an den Henker.","effect":"exposed","requiresRoles":true,"drinking":false},"im-dunkeln-sind-alle-ratten-grau":{"pos":70,"name":"Im Dunkeln sind alle Ratten grau","category":"Segen","visibility":"public","description":"Eine Fackel erlischt, und im Dunkeln klimpert es unter dem Tisch: Der Kerkermeister hat beim Zählen seinen Beutel fallen lassen und sucht ihn jetzt an der falschen Stelle. Wer sich noch nicht verraten hat, kann in Ruhe danach tasten, denn auf ihn achtet keiner. Alle, deren Rolle noch nicht erraten wurde, erhalten 1 Münze.","effect":"disguise","requiresRoles":true,"drinking":false},"das-gnadengesuch":{"pos":140,"name":"Das Gnadengesuch","category":"Entscheidung","visibility":"public","description":"Der Ärmste darf ein Gnadengesuch an den Kerkermeister richten, und der schnieft gerührt in seinen Bart. Wer die wenigsten Münzen hat, entscheidet: Alle erhalten 1 Münze, oder er selbst erhält 2 Münzen.","effect":"crossroads","requiresRoles":false,"drinking":false},"die-letzte-brotkruste":{"pos":150,"name":"Die letzte Brotkruste","category":"Entscheidung","visibility":"public","description":"Im Verlies teilt man, oder man wird geteilt. Wer die meisten Münzen hat, schenkt einem Mitspieler seiner Wahl 2 Münzen oder zahlt 3 Münzen an die Spielbank.","effect":"generosity","requiresRoles":false,"drinking":false},"die-muenze-aus-dem-totenschaedel":{"pos":160,"name":"Die Münze aus dem Totenschädel","category":"Glück","visibility":"public","description":"Der Kerkermeister fischt eine alte Münze aus einem Totenschädel und möchte wissen, ob das Glück noch hier unten wohnt. Reihum sagt jeder „Kopf“ oder „Zahl“, dann wirft sein linker Nachbar eine echte Münze. Wer richtig angesagt hat, erhält 1 Münze, wer falsch lag, verliert 1 Münze. Tragt das Ergebnis für jeden in der App ein.","effect":"fateManual","requiresRoles":false,"drinking":false},"gustav-bringt-ein-geschenk":{"pos":190,"name":"Gustav bringt ein Geschenk","category":"Glück","visibility":"public","description":"Gustav, die Ratte, schleppt einen Beutel aus den Katakomben heran und legt ihn vor einen Gefangenen. Wem, entscheidet nur die Ratte. Die App lost einen Gefangenen aus, er erhält 3 Münzen.","effect":"lottery","requiresRoles":false,"drinking":false},"der-erste-krug":{"pos":201,"name":"Der erste Krug","category":"Rausch","visibility":"public","description":"Der Kerkermeister zapft sich am Fass unter dem Tisch den ersten Krug des Abends, bläst den Schaum über eure Köpfe und leert ihn in einem Zug. Dann zählt er seinen Schlüsselbund nach, zweimal, mit gerunzelter Stirn. Beim dritten Mal verzählt er sich und lacht zum ersten Mal an diesem Abend. „Ist ja Feiertag“, brummt er. Ein Schlüssel kostet ab sofort 1 Münze weniger.","effect":"jailerDrinks","requiresRoles":false},"das-lied-vom-henkersknoten":{"pos":202,"name":"Das Lied vom Henkersknoten","category":"Rausch","visibility":"public","description":"Der zweite Krug macht den Kerkermeister musikalisch. Er stimmt das Lied vom Henkersknoten an, alle elf Strophen, und schlägt mit dem Schlüsselbund den Takt auf die Tischplatte. Wer nicht mitsingt, bekommt einen bösen Blick. Wer mitsingt, bekommt einen Freundschaftspreis. Bei der siebten Strophe weiß er nicht mehr weiter und singt einfach noch einmal die erste. Ein Schlüssel kostet ab sofort 1 Münze weniger.","effect":"jailerDrinks","requiresRoles":false},"traenen-im-bier":{"pos":203,"name":"Tränen im Bier","category":"Rausch","visibility":"public","description":"Beim dritten Krug wird der Kerkermeister rührselig. Mit zitternder Stimme erzählt er von seiner Mutter, die immer sagte, aus ihm werde einmal etwas Großes, und von dem Tag, an dem er stattdessen hier unten landete. Dicke Tränen tropfen in sein Bier. Er schnäuzt sich in den Ärmel, tätschelt dem nächstbesten Gefangenen die Wange und schluchzt: „Ihr seid die Einzigen, die mir je zugehört haben.“ Ein Schlüssel kostet ab sofort 1 Münze weniger.","effect":"jailerDrinks","requiresRoles":false},"der-tanz-mit-dem-gerippe":{"pos":204,"name":"Der Tanz mit dem Gerippe","category":"Rausch","visibility":"public","description":"Nach dem vierten Krug hält es den Kerkermeister nicht mehr auf der Bank. Er holt das alte Gerippe aus Zelle sieben, legt ihm den Arm um die Hüfte und tanzt mit ihm eine Polka über den Tisch, mitten durch den Eintopf. Das Gerippe verliert dabei einen Arm, der Kerkermeister beinahe seine Hose. Als er keuchend wieder sitzt, hängt der Schlüsselbund nur noch lose an seinem Gürtel. Ein Schlüssel kostet ab sofort 1 Münze weniger.","effect":"jailerDrinks","requiresRoles":false},"der-letzte-tropfen":{"pos":205,"name":"Der letzte Tropfen","category":"Rausch","visibility":"public","description":"Das Fass ist leer. Der Kerkermeister kippt es über seinem Krug aus, schüttelt es, horcht hinein und leckt zuletzt den Zapfhahn ab. Dann hält er Gustav, die Ratte, für den Burgherrn, sinkt vor ihr auf die Knie und schwört ihr ewige Treue. Als er sich am Tisch wieder hochgezogen hat, blinzelt er in die Runde: „Zwei Münzen, und der Schlüssel gehört euch. Wer seid ihr eigentlich?“ Billiger wird es nicht mehr, weiter als bis zwei zählt er heute nicht. Ein Schlüssel kostet ab sofort 1 Münze weniger.","effect":"jailerDrinks","requiresRoles":false},"fund-im-eintopf":{"pos":210,"name":"Fund im Eintopf","category":"Glück","visibility":"private","description":"Du fischst etwas Hartes aus deinem Eintopf. Kein Zahn, sondern zwei Münzen! Wem sie vorher gehörten, fragst du lieber nicht. Du erhältst 2 Münzen.","privateType":"instant","privateCoins":2},"rattenbiss":{"pos":220,"name":"Rattenbiss","category":"Pech","visibility":"private","description":"Gustav, die Ratte, beißt dich in den großen Zeh und verschwindet mit einer deiner Münzen im Mauerloch. Du verlierst 1 Münze.","privateType":"instant","privateCoins":-1},"das-lose-mauerstueck":{"pos":230,"name":"Das lose Mauerstück","category":"Glück","visibility":"private","description":"Hinter deinem Rücken wackelt ein Stein in der Wand. Dahinter liegt das Versteck eines früheren Gefangenen. Er braucht es nicht mehr. Du erhältst 3 Münzen.","privateType":"instant","privateCoins":3},"der-henker-nimmt-mass":{"pos":240,"name":"Der Henker nimmt Maß","category":"Pech","visibility":"private","description":"Der Henker schleicht vorbei und misst mit einem Seil deinen Hals ab. Vor Schreck lässt du zwei Münzen fallen, und eine Ratte ist schneller. Du verlierst 2 Münzen.","privateType":"instant","privateCoins":-2},"eine-verwechslung":{"pos":250,"name":"Eine Verwechslung","category":"Glück","visibility":"private","description":"Der Kerkermeister hält dich für seine verstorbene Mutter, weint sich an deiner Schulter aus und steckt dir eine Münze zu. Lass ihn in dem Glauben. Du erhältst 1 Münze.","privateType":"instant","privateCoins":1},"das-zauberwort":{"pos":260,"name":"Das Zauberwort","category":"Geheimer Auftrag","visibility":"private","description":"Bring einen Mitspieler dazu, das Wort „Henker“ zu sagen, ohne dass du es vorher selbst sagst. Schaffst du es, erhältst du 2 Münzen.","privateType":"task","privateCoins":2},"ein-hoch-auf-den-kerkermeister":{"pos":270,"name":"Ein Hoch auf den Kerkermeister","category":"Geheimer Auftrag","visibility":"private","description":"Bring mindestens drei Mitspieler dazu, gleichzeitig mit dir auf den Kerkermeister anzustoßen. Wasser zählt genauso. Schaffst du es, erhältst du 3 Münzen.","privateType":"task","privateCoins":3},"geisterstunde":{"pos":280,"name":"Geisterstunde","category":"Geheimer Auftrag","visibility":"private","description":"Bring zwei Mitspieler dazu, gleichzeitig mit dir wie ein Gespenst „Huuuu!“ zu heulen. Schaffst du es, erhältst du 2 Münzen.","privateType":"task","privateCoins":2},"mundraub":{"pos":290,"name":"Mundraub","category":"Geheimer Auftrag","visibility":"private","description":"Bring einen Mitspieler dazu, dir freiwillig etwas von seinem Teller oder aus seinem Glas anzubieten. Schaffst du es, erhältst du 2 Münzen.","privateType":"task","privateCoins":2},"unschuldig":{"pos":300,"name":"Unschuldig!","category":"Geheimer Auftrag","visibility":"private","description":"Erzähl einem Mitspieler, warum du völlig zu Unrecht hier unten sitzt, bis er laut sagt, dass er dir glaubt. Schaffst du es, erhältst du 2 Münzen.","privateType":"task","privateCoins":2},"kopfgeld":{"pos":310,"name":"Kopfgeld","category":"Segen, hält an","visibility":"public","description":"Der Kerkermeister ist schrecklich neugierig und hört nichts lieber als eine gute Gefangenengeschichte. Doch hier unten will keiner reden. Wer ihm trotzdem etwas Wahres verrät, wird belohnt. Bis zur nächsten zufällig gezogenen Ereigniskarte bringt ein richtiger Tipp beim Raten 4 statt 3 Münzen. Gekaufte geheime Ereigniskarten beenden die Wirkung nicht.","effect":"bounty","requiresRoles":true,"drinking":false},"gefluester-zum-halben-preis":{"pos":320,"name":"Geflüster zum halben Preis","category":"Segen, hält an","visibility":"public","description":"Durch die Gitter von Zelle dreizehn flüstert die Wahrsagerin: „Heute zum halben Preis, meine Täubchen.“ Bis zur nächsten zufällig gezogenen Ereigniskarte kostet eine geheime Ereigniskarte 1 statt 2 Münzen. Gekaufte geheime Ereigniskarten beenden die Wirkung nicht.","effect":"secretSale","requiresRoles":false,"drinking":false},"der-kerkermeister-verrechnet-sich":{"pos":330,"name":"Der Kerkermeister verrechnet sich","category":"hält an","visibility":"public","description":"Der Kerkermeister zählt an seinen Fingern nach und kommt jedes Mal auf etwas anderes. Am Ende ist er felsenfest überzeugt, ein Schlüssel habe schon immer 4 Münzen gekostet, und lässt sich davon nicht mehr abbringen. Bis zur nächsten zufällig gezogenen Ereigniskarte kostet ein Schlüssel 4 Münzen, ganz gleich, was er vorher gekostet hat. Gekaufte geheime Ereigniskarten beenden die Wirkung nicht.","effect":"keyPriceSet","requiresRoles":false,"drinking":false},"teure-geruechte":{"pos":340,"name":"Teure Gerüchte","category":"Fluch, hält an","visibility":"public","description":"Der Schreiber des Henkers lauscht an der Tür und notiert jede Vermutung, die er hört. Wer laut rät, muss ihm sein Schweigen abkaufen. Bis zur nächsten zufällig gezogenen Ereigniskarte kostet Raten 2 statt 1 Münze. Gekaufte geheime Ereigniskarten beenden die Wirkung nicht.","effect":"costlyGuess","requiresRoles":true,"drinking":false},"taschen-leeren":{"pos":350,"name":"Taschen leeren!","category":"Enthüllung","visibility":"public","description":"Ein Gerücht macht die Runde: Einer von euch hat dem Kerkermeister heimlich Schlüssel abgeluchst. Auf „Eins, zwei, drei, Taschen leeren!“ zeigen alle gleichzeitig auf den, den sie verdächtigen. Wer die meisten Finger auf sich hat, wählt: Er zahlt 2 Münzen an die Spielbank, oder er zeigt allen, welche Schlüssel er schon hat. Bei Gleichstand entscheidet jeder der Gleichplatzierten für sich.","effect":"searchPockets","requiresRoles":false,"drinking":false},"weihwasser-gegen-gespenster":{"pos":360,"name":"Weihwasser gegen Gespenster","category":"Trinkrunde","visibility":"public","description":"Der Kerkermeister kommt mit einer staubigen Flasche aus dem Keller. Er ist sich ganz sicher, dass darin Weihwasser gegen die Gespenster ist. Es ist Schnaps. Wer die wenigsten Münzen hat, ist jetzt Mundschenk und schenkt jedem einen Kurzen ein. Dann stoßen alle gemeinsam an: „Gegen die Gespenster!“","effect":"spotlightFewest","requiresRoles":false,"drinking":true},"ueber-geld-spricht-man-nicht":{"pos":370,"name":"Über Geld spricht man nicht","category":"Trinkregel","visibility":"public","description":"Die Kerkerköchin kann das ewige Gerede über Geld nicht mehr hören und droht mit der Kelle: „Wer jetzt noch vom Geld anfängt, der kriegt die Kelle zu spüren!“ Bis zum nächsten Minispiel spricht niemand mehr über Münzen, Taler oder Gold. Auch ähnliche Wörter und alles, was dasselbe meint, sind verboten. Erlaubt sind sie nur, wenn jemand sie aus der App vorliest. Wer es trotzdem tut und erwischt wird, trinkt einen Schluck.","effect":"untilMinigame","requiresRoles":false,"drinking":true},"der-wasserfall-der-katakomben":{"pos":380,"name":"Der Wasserfall der Katakomben","category":"Trinkrunde","visibility":"public","description":"Durch die Decke tropft es, erst langsam, dann immer mehr: Oben in der Halle ist ein Fass umgekippt. Legt eine Reihenfolge fest: Wer am wenigsten im Glas hat, kommt zuerst, wer am meisten hat, zuletzt. Auf „Prost!“ setzen alle gleichzeitig an. Der Erste darf aufhören, wann er will. Jeder andere darf erst aufhören, wenn der vor ihm aufgehört hat. Wer sein Glas leer hat, hört auf.","effect":"calm","requiresRoles":false,"drinking":true},"auf-alles-und-jeden":{"pos":390,"name":"Auf alles und jeden","category":"Trinkrunde","visibility":"public","description":"Der Kerkermeister will unbedingt anstoßen, weiß aber nicht mehr, worauf. Wem zuerst ein Trinkspruch einfällt, steht auf und beginnt. Danach darf jeder, der mag, einen weiteren Trinkspruch ausbringen, auch mehrmals. Nach jedem Trinkspruch trinken alle gemeinsam einen Schluck. Fällt niemandem mehr etwas ein, ist die Runde vorbei.","effect":"calm","requiresRoles":false,"drinking":true},"zahltag-im-verlies":{"pos":400,"name":"Zahltag im Verlies","category":"Trinkrunde","visibility":"public","description":"Heute wird nicht mit Münzen bezahlt, sondern mit Schlücken. Reihum bestimmt jeder eine Person und verteilt so viele Schlücke an sie, wie er gerade Münzen hat. Die Münzen selbst behält er.","effect":"coinCount","requiresRoles":false,"drinking":true},"die-runde-des-reichen":{"pos":410,"name":"Die Runde des Reichen","category":"Trinkrunde","visibility":"public","description":"Wer am meisten hat, gibt einen aus. Wer die meisten Münzen hat, bestimmt zwei Mitspieler, die mit ihm einen Schluck trinken. Bei Gleichstand bestimmt jeder der Reichsten einen.","effect":"spotlightMost","requiresRoles":false,"drinking":true}}}}};
